// --- CUSTOM HOOK ---
const useEmotionSocket = (serverUrl: string) => {
    const socketRef = useRef<Socket | null>(null);
    const [isConnected, setIsConnected] = useState(false);
    const [emotion, setEmotion] = useState<Emotion>('neutral');

    useEffect(() => {
        const socket = io(serverUrl);
        socketRef.current = socket;
        socket.on('connect', () => setIsConnected(true));
        socket.on('disconnect', () => setIsConnected(false));
        socket.on('emotion_update', (data: { emotion: Emotion }) => setEmotion(data.emotion));
        return () => { socket.disconnect(); };
    }, [serverUrl]);

    const sendFrame = useCallback((frame: string) => {
        if (socketRef.current && socketRef.current.connected) {
            socketRef.current.emit('video_frame', { frame });
        }
    }, []);

    return { emotion, isConnected, sendFrame };
};

