const EmotionGalaxy = () => {
    const EmotionNode = ({ position, color, emotion }: { position: [number, number, number], color: string, emotion: Emotion }) => {
        const ref = useRef<any>();
        useFrame((state, delta) => {
            ref.current.rotation.y += 0.005;
            ref.current.position.y = position[1] + Math.sin(state.clock.elapsedTime + position[0]) * 0.2;
        });
        return (
            <group ref={ref} position={position}>
                <Text color="white" anchorX="center" anchorY="middle" fontSize={0.3} position={[0, 0.7, 0]}>
                    {emotion}
                </Text>
                <mesh>
                    <sphereGeometry args={[0.5, 32, 32]} />
                    <meshStandardMaterial color={color} emissive={color} emissiveIntensity={2} toneMapped={false}/>
                </mesh>
            </group>
        );
    };

    return (
        <div className="w-full h-screen my-24">
             <h2 className="text-3xl font-bold mb-6 text-center">Explore the Emotion Galaxy</h2>
            <Canvas camera={{ position: [0, 0, 8]}}>
                <ambientLight intensity={0.3} />
                <pointLight position={[10, 10, 10]} color="white"/>
                <Suspense fallback={null}>
                    <EmotionNode position={[-4, 0, 0]} color="#FFD700" emotion="happy" />
                    <EmotionNode position={[4, 0, 0]} color="#6A5ACD" emotion="sad" />
                    <EmotionNode position={[0, 3, -2]} color="#FF0000" emotion="angry" />
                    <EmotionNode position={[0, -3, -2]} color="#FFFFFF" emotion="neutral" />
                    <Stars radius={100} depth={50} count={5000} factor={4} saturation={0} fade speed={1} />
                </Suspense>
            </Canvas>
        </div>
    );
};

export default function HomePage() {
  const { emotion: liveEmotion, isConnected, sendFrame } = useEmotionSocket('http://127.0.0.1:5000');
  const [isWebcamActive, setIsWebcamActive] = useState(false);
  const [simulatedEmotion, setSimulatedEmotion] = useState<Emotion>('neutral');
  const emotion = isWebcamActive ? liveEmotion : simulatedEmotion;
  const [quotes, setQuotes] = useState<Quote[]>([{ quote: "Welcome to the new MindMorph experience.", author: "Scroll down to begin." }]);
  const [hasMounted, setHasMounted] = useState(false);
  const currentStyle = emotionStyles[emotion] || emotionStyles.neutral;
  const webcamRef = useRef<Webcam>(null);

  useEffect(() => { setHasMounted(true); }, []);

  const fetchQuotes = useCallback(async (currentEmotion: Emotion) => {
      setQuotes(fallbackQuotes[currentEmotion] || fallbackQuotes.neutral);
  }, []);

  useEffect(() => { fetchQuotes(emotion); }, [emotion, fetchQuotes]);
  
  const captureFrame = useCallback(() => {
    if (isWebcamActive && webcamRef.current) {
        const imageSrc = webcamRef.current.getScreenshot();
        if (imageSrc) sendFrame(imageSrc);
    }
  }, [isWebcamActive, sendFrame]);

  useEffect(() => {
    const interval = setInterval(captureFrame, 500);
    return () => clearInterval(interval);
  }, [captureFrame]);

  return (
    <div className="bg-black text-white">
      <section className="h-screen w-full relative flex flex-col items-center justify-center overflow-hidden">
          {hasMounted && <Particles />}
          <motion.div className="absolute inset-0 z-0" animate={{ background: `radial-gradient(circle at 50% 50%, transparent, black 70%), radial-gradient(ellipse at 40% 60%, ${currentStyle.auroraColors[0]} 0%, transparent 80%), radial-gradient(ellipse at 60% 40%, ${currentStyle.auroraColors[1]} 0%, transparent 80%)` }} transition={{ duration: 2.0, ease: "easeInOut" }} />
          <header className="absolute top-0 left-0 w-full p-6 flex justify-between items-center z-20">
             <h1 className="text-xl font-bold tracking-wider">MindMorph</h1>
             <TimeOfDayGreeting />
          </header>
          <div className="relative z-10 text-center -mt-16">
              <div className="relative w-72 h-72 mb-4">
                  <motion.div className="absolute inset-0 rounded-full" style={{ background: `radial-gradient(circle at center, ${currentStyle.orbColor} 0%, transparent 60%)`, boxShadow: `0 0 60px ${currentStyle.orbColor}` }} animate={{ scale: [1, 1.03, 1], transition: { duration: 5, repeat: Infinity, ease: "easeInOut" } }} />
                  <motion.div className="absolute inset-10 rounded-full border-2 border-white/20" animate={{ rotate: 360 }} transition={{ duration: 25, repeat: Infinity, ease: 'linear' }} />
                  <div className="w-full h-full flex items-center justify-center"><span className="text-4xl font-bold capitalize tracking-widest">{isWebcamActive ? emotion : "?"}</span></div>
              </div>
              <AnimatedQuote quotes={quotes} isLoading={false} />
          </div>
          <div className="absolute bottom-8 right-8 z-20">
               <motion.button whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.9 }} onClick={() => setIsWebcamActive(!isWebcamActive)} className={`w-20 h-20 rounded-full border border-white/20 backdrop-blur-lg flex items-center justify-center text-white/70 hover:text-white transition-all duration-300 ${isWebcamActive ? 'bg-red-500/50' : 'bg-white/10'}`}>
                   {isWebcamActive ? <VideoOff size={28} /> : <Zap size={28} />}
               </motion.button>
          </div>
          {isWebcamActive && <div className="absolute bottom-8 left-8 w-48 h-27 rounded-lg shadow-2xl border border-white/10 overflow-hidden z-20"><Webcam ref={webcamRef} audio={false} className="w-full h-full object-cover" mirrored /></div>}
      </section>

      <div className="flex flex-col items-center px-4">
        <MindMetrics emotion={emotion} />
        <div className="w-full max-w-4xl grid grid-cols-1 md:grid-cols-2 gap-8 my-16">
            <AI_CoachChat />
            <MindfulChallenges />
        </div>
        <EmotionGalaxy />
      </div>
    </div>
  );
}

